import React from "react";
import UserStore from "../../store/UserStore";
import classes from "./Login.module.css";
const Loginmodal = () => {
  function handleSubmit(event) {
    event.preventDefault();
    const username = event.target.username.value;
    const password = event.target.password.value;
    UserStore.login(username, password);
  }
  return (
    <div>
      <aside className={classes.modal_login}>
        <p>Вход</p>
        <form action="" onSubmit={handleSubmit}>
          <input type="text" name="username" id="" placeholder="Логин" />
          <input type="text" name="password" id="" placeholder="Пароль" />
          <label htmlFor="auto-enter">
            <input type="checkbox" name="auto-enter" id="auto-enter" />
          </label>
          <button type="submit"></button>
        </form>
      </aside>
    </div>
  );
};

export default Loginmodal;
